```html
<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>埃瑟尔德大陆 - 角色创建</title>
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">
    <link href="https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@400;700&family=Kaiti&display=swap" rel="stylesheet">
    <style>
        /* ==================== 羊皮纸主题变量 ==================== */
        :root {
            /* 羊皮纸背景 */
            --parchment-bg: #f4e4bc;
            --parchment-dark: #d4c4a0;
            --parchment-light: #faf0dc;
            --parchment-card: #faf6eb;

            /* 墨水/文字 */
            --ink-primary: #3d2914;
            --ink-secondary: #5c4033;
            --ink-light: #8b7355;

            /* 装饰/边框 */
            --border-gold: #b8860b;
            --border-dark: #8b4513;
            --accent-red: #8b0000;
            --accent-blue: #1e3a5f;
            --accent-gold: #d4af37;
            --accent-orange: #e67e22;
            --bg-dark: #2c1810;
            --text-primary: #f4e4bc;

            /* 资源条颜色 */
            --hp-color: #c0392b;
            --sp-color: #d68910;
            --mp-color: #2980b9;

            /* 状态效果 */
            --success: #2e7d32;
            --warning: #f9a825;
            --danger: #c62828;

            /* 阴影 */
            --shadow-light: 2px 2px 8px rgba(61, 41, 20, 0.15);
            --shadow-medium: 4px 4px 12px rgba(61, 41, 20, 0.25);

            /* 字体 */
            --font-title: 'Noto Serif SC', serif;
            --font-main: 'Kaiti', 'Noto Serif SC', serif;
        }

        /* ==================== 基础样式 ==================== */
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: var(--font-main);
            background: var(--parchment-bg);
            background-image:
                url("data:image/svg+xml,%3Csvg width='100' height='100' viewBox='0 0 100 100' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.8' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='0.08'/%3E%3C/svg%3E");
            color: var(--ink-primary);
            padding: 15px;
            min-height: 100vh;
        }

        /* ==================== 主容器 ==================== */
        .main-container {
            max-width: 900px;
            margin: 0 auto;
        }

        /* ==================== 页面标题 ==================== */
        .page-header {
            text-align: center;
            padding: 30px 20px;
            margin-bottom: 20px;
            background: var(--parchment-card);
            border: 2px solid var(--border-dark);
            border-radius: 8px;
            box-shadow: var(--shadow-medium);
            position: relative;
        }

        .page-header::before {
            content: '';
            position: absolute;
            top: 4px;
            left: 4px;
            right: 4px;
            bottom: 4px;
            border: 1px solid var(--border-gold);
            border-radius: 4px;
            pointer-events: none;
            opacity: 0.5;
        }

        .page-title {
            font-size: 2.2rem;
            font-family: var(--font-title);
            color: var(--accent-red);
            text-shadow: 2px 2px 4px rgba(0,0,0,0.2);
            margin-bottom: 10px;
        }

        .page-subtitle {
            font-size: 1.1rem;
            color: var(--ink-light);
            font-style: italic;
        }

        /* ==================== 羊皮纸卡片 ==================== */
        .parchment-card {
            background: var(--parchment-card);
            border: 2px solid var(--border-dark);
            border-radius: 8px;
            padding: 20px;
            margin-bottom: 15px;
            box-shadow: var(--shadow-medium);
            position: relative;
        }

        .parchment-card::before {
            content: '';
            position: absolute;
            top: 4px;
            left: 4px;
            right: 4px;
            bottom: 4px;
            border: 1px solid var(--border-gold);
            border-radius: 4px;
            pointer-events: none;
            opacity: 0.5;
        }

        .card-title {
            font-size: 1.2rem;
            font-weight: bold;
            color: var(--accent-red);
            margin-bottom: 15px;
            padding-bottom: 10px;
            border-bottom: 1px solid var(--border-dark);
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .card-title::before {
            content: '✦';
            color: var(--border-gold);
        }

        /* ==================== 表单元素 ==================== */
        .form-row {
            display: flex;
            gap: 15px;
            flex-wrap: wrap;
            margin-bottom: 15px;
        }

        .form-group {
            flex: 1;
            min-width: 200px;
        }

        .form-group.full-width {
            width: 100%;
            flex: none;
        }

        .form-label {
            display: block;
            font-size: 0.95rem;
            color: var(--ink-secondary);
            margin-bottom: 6px;
            font-weight: bold;
        }

        .form-input,
        .form-select,
        .form-textarea {
            width: 100%;
            background-color: var(--parchment-light);
            color: var(--ink-primary);
            border: 1px solid var(--border-dark);
            border-radius: 6px;
            padding: 10px 12px;
            font-size: 1rem;
            font-family: var(--font-main);
            transition: all 0.3s ease;
        }

        .form-input:focus,
        .form-select:focus,
        .form-textarea:focus {
            outline: none;
            border-color: var(--border-gold);
            box-shadow: 0 0 0 2px rgba(184, 134, 11, 0.2);
        }

        .form-textarea {
            min-height: 120px;
            resize: vertical;
        }

        .form-select {
            cursor: pointer;
        }

        /* ==================== 种族天赋显示 ==================== */
        .talent-display {
            background: var(--parchment-light);
            border: 1px solid var(--border-gold);
            border-radius: 6px;
            padding: 15px;
            margin-top: 10px;
        }

        .talent-item {
            display: flex;
            align-items: flex-start;
            gap: 10px;
            margin-bottom: 10px;
            padding-bottom: 10px;
            border-bottom: 1px dashed var(--border-dark);
        }

        .talent-item:last-child {
            margin-bottom: 0;
            padding-bottom: 0;
            border-bottom: none;
        }

        .talent-icon {
            color: var(--border-gold);
            font-size: 1.1rem;
        }

        .talent-content {
            flex: 1;
        }

        .talent-name {
            font-weight: bold;
            color: var(--accent-red);
            margin-bottom: 3px;
        }

        .talent-desc {
            font-size: 0.9rem;
            color: var(--ink-secondary);
        }

        .special-note {
            background: rgba(139, 0, 0, 0.1);
            border: 1px solid var(--accent-red);
            border-radius: 4px;
            padding: 10px;
            margin-top: 10px;
            font-size: 0.9rem;
            color: var(--accent-red);
        }

        .special-note i {
            margin-right: 5px;
        }

        /* ==================== 属性加点系统 ==================== */
        .stats-container {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 15px;
        }

        .stat-item {
            background: var(--parchment-light);
            border: 1px solid var(--border-dark);
            border-radius: 6px;
            padding: 12px;
        }

        .stat-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 8px;
        }

        .stat-name {
            font-weight: bold;
            color: var(--ink-primary);
        }

        .stat-values {
            font-size: 0.85rem;
            color: var(--ink-light);
        }

        .stat-bar-container {
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .stat-bar {
            flex: 1;
            height: 20px;
            background: var(--parchment-dark);
            border-radius: 10px;
            overflow: hidden;
            position: relative;
        }

        .stat-bar-fill {
            height: 100%;
            background: linear-gradient(90deg, var(--border-gold), var(--accent-red));
            border-radius: 10px;
            transition: width 0.3s ease;
        }

        .stat-controls {
            display: flex;
            align-items: center;
            gap: 5px;
        }

        .stat-btn {
            width: 28px;
            height: 28px;
            border: 1px solid var(--border-dark);
            background: var(--parchment-card);
            color: var(--ink-primary);
            border-radius: 4px;
            cursor: pointer;
            font-size: 1rem;
            font-weight: bold;
            transition: all 0.2s ease;
        }

        .stat-btn:hover:not(:disabled) {
            background: var(--border-gold);
            color: white;
        }

        .stat-btn:disabled {
            opacity: 0.5;
            cursor: not-allowed;
        }

        .stat-total {
            min-width: 30px;
            text-align: center;
            font-weight: bold;
            color: var(--accent-red);
        }

        .points-remaining {
            background: linear-gradient(135deg, var(--border-gold), var(--accent-red));
            color: white;
            padding: 10px 20px;
            border-radius: 20px;
            font-weight: bold;
            text-align: center;
            margin-bottom: 15px;
        }

        /* ==================== 装备预览 ==================== */
        .equipment-preview {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 15px;
        }

        .equipment-section {
            background: var(--parchment-light);
            border: 1px solid var(--border-dark);
            border-radius: 6px;
            padding: 12px;
        }

        .equipment-section-title {
            font-weight: bold;
            color: var(--accent-red);
            margin-bottom: 10px;
            padding-bottom: 5px;
            border-bottom: 1px dashed var(--border-dark);
        }

        .equipment-item {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 6px 0;
            border-bottom: 1px dotted var(--border-dark);
        }

        .equipment-item:last-child {
            border-bottom: none;
        }

        .equipment-name {
            color: var(--ink-primary);
        }

        .equipment-source {
            font-size: 0.8rem;
            color: var(--ink-light);
            background: var(--parchment-dark);
            padding: 2px 6px;
            border-radius: 3px;
        }

        .equipment-bonus {
            font-size: 0.85rem;
            color: var(--success);
        }

        /* ==================== 资源预览 ==================== */
        .resource-preview {
            display: flex;
            gap: 20px;
            flex-wrap: wrap;
            margin-top: 15px;
            padding: 15px;
            background: var(--parchment-light);
            border-radius: 6px;
        }

        .resource-item {
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .resource-icon {
            width: 24px;
            height: 24px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            color: white;
            font-size: 0.8rem;
        }

        .resource-icon.hp { background: var(--hp-color); }
        .resource-icon.sp { background: var(--sp-color); }
        .resource-icon.mp { background: var(--mp-color); }

        .resource-value {
            font-weight: bold;
            color: var(--ink-primary);
        }

        /* ==================== 按钮样式 ==================== */
        .btn-group {
            display: flex;
            gap: 15px;
            flex-wrap: wrap;
            justify-content: center;
            margin-top: 20px;
        }

        .btn {
            padding: 12px 30px;
            border: 2px solid var(--border-dark);
            border-radius: 8px;
            font-size: 1.1rem;
            font-family: var(--font-title);
            font-weight: bold;
            cursor: pointer;
            transition: all 0.3s ease;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .btn-primary {
            background: linear-gradient(135deg, var(--border-gold), var(--accent-red));
            color: white;
            border-color: var(--accent-red);
        }

        .btn-primary:hover {
            transform: translateY(-2px);
            box-shadow: 0 4px 12px rgba(139, 0, 0, 0.3);
        }

        .btn-secondary {
            background: var(--parchment-card);
            color: var(--ink-primary);
        }

        .btn-secondary:hover {
            background: var(--parchment-dark);
        }

        .btn-success {
            background: linear-gradient(135deg, #2e7d32, #1b5e20);
            color: white;
            border-color: #1b5e20;
        }

        .btn-success:hover {
            transform: translateY(-2px);
            box-shadow: 0 4px 12px rgba(46, 125, 50, 0.3);
        }

        /* ==================== 存档模态框 ==================== */
        .modal-overlay {
            display: none;
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: rgba(0, 0, 0, 0.6);
            z-index: 1000;
            justify-content: center;
            align-items: center;
        }

        .modal-overlay.active {
            display: flex;
        }

        .modal-content {
            background: var(--parchment-card);
            border: 2px solid var(--border-dark);
            border-radius: 8px;
            padding: 25px;
            max-width: 500px;
            width: 90%;
            max-height: 80vh;
            overflow-y: auto;
            position: relative;
        }

        .modal-content::before {
            content: '';
            position: absolute;
            top: 4px;
            left: 4px;
            right: 4px;
            bottom: 4px;
            border: 1px solid var(--border-gold);
            border-radius: 4px;
            pointer-events: none;
            opacity: 0.5;
        }

        .modal-title {
            font-size: 1.3rem;
            color: var(--accent-red);
            margin-bottom: 20px;
            padding-bottom: 10px;
            border-bottom: 1px solid var(--border-dark);
        }

        .modal-close {
            position: absolute;
            top: 15px;
            right: 15px;
            background: none;
            border: none;
            font-size: 1.5rem;
            cursor: pointer;
            color: var(--ink-light);
        }

        .save-slot {
            background: var(--parchment-light);
            border: 1px solid var(--border-dark);
            border-radius: 6px;
            padding: 12px;
            margin-bottom: 10px;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .save-info {
            flex: 1;
        }

        .save-name {
            font-weight: bold;
            color: var(--ink-primary);
        }

        .save-details {
            font-size: 0.85rem;
            color: var(--ink-light);
        }

        .save-actions {
            display: flex;
            gap: 8px;
        }

        .save-btn {
            padding: 6px 12px;
            border: 1px solid var(--border-dark);
            border-radius: 4px;
            cursor: pointer;
            font-size: 0.85rem;
            transition: all 0.2s ease;
        }

        .save-btn.load {
            background: var(--border-gold);
            color: white;
        }

        .save-btn.delete {
            background: var(--accent-red);
            color: white;
        }

        .save-btn:hover {
            opacity: 0.8;
        }

        .no-saves {
            text-align: center;
            color: var(--ink-light);
            padding: 20px;
        }

        /* ==================== 提示消息 ==================== */
        .toast {
            position: fixed;
            bottom: 20px;
            left: 50%;
            transform: translateX(-50%);
            background: var(--ink-primary);
            color: var(--parchment-light);
            padding: 12px 25px;
            border-radius: 8px;
            z-index: 2000;
            opacity: 0;
            transition: opacity 0.3s ease;
        }

        .toast.show {
            opacity: 1;
        }

        .toast.success {
            background: var(--success);
        }

        .toast.error {
            background: var(--danger);
        }

        /* ==================== 自定义职业模态框 ==================== */
        .modal-overlay {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0, 0, 0, 0.7);
            display: none;
            justify-content: center;
            align-items: center;
            z-index: 1000;
        }

        .modal-content {
            background: var(--parchment-dark);
            border: 2px solid var(--border-gold);
            border-radius: 8px;
            padding: 20px;
            max-width: 90%;
            max-height: 90vh;
            display: flex;
            flex-direction: column;
            overflow: hidden;
            box-shadow: 0 0 20px rgba(0, 0, 0, 0.5);
        }

        .modal-content .modal-scroll-area {
            flex: 1;
            overflow-y: auto;
            min-height: 0;
        }

        .modal-content .modal-footer {
            flex-shrink: 0;
            padding-top: 12px;
            border-top: 1px solid var(--border-gold);
            margin-top: 12px;
        }

        .form-control {
            background: var(--bg-dark);
            border: 1px solid var(--border-dark);
            color: var(--text-primary);
            border-radius: 4px;
            font-size: 14px;
        }

        .form-control:focus {
            outline: none;
            border-color: var(--accent-gold);
        }

        /* ==================== 响应式设计 ==================== */
        @media (max-width: 600px) {
            body {
                padding: 10px;
            }

            .page-title {
                font-size: 1.6rem;
            }

            .form-row {
                flex-direction: column;
            }

            .btn-group {
                flex-direction: column;
            }

            .btn {
                width: 100%;
                justify-content: center;
            }
        }
    </style>
</head>
<body>
    <div class="main-container">
        <!-- 页面标题 -->
        <div class="page-header">
            <h1 class="page-title">埃瑟尔德大陆</h1>
            <p class="page-subtitle">命运之轮已开始转动，你的传奇由此刻开启</p>
        </div>

        <!-- 背景介绍 -->
        <div class="parchment-card">
            <div class="card-title">欢迎来到埃瑟尔德大陆</div>
            <p style="line-height: 1.8; text-indent: 2em;">
                埃瑟尔德大陆，一片充满魔法与奇迹的土地。在这里，诸多种族共同生活，从繁华的诺顿王国王城到神秘的幽暗密林，从工业重镇铁炉堡到危险的暮光沼泽。圣光教会的信仰遍布大陆，古老的精灵在森林中守护着自然的秘密，矮人在山脉中锻造着传世之作，而北方的兽人部落则时刻威胁着文明的边界。
            </p>
            <p style="line-height: 1.8; text-indent: 2em; margin-top: 10px;">
                现在，你将在这片大陆上开启属于自己的冒险。选择你的种族、职业，决定你的起点，书写你的传奇故事。
            </p>
        </div>

        <!-- 基本信息 -->
        <div class="parchment-card">
            <div class="card-title">基本信息</div>
            <div class="form-row">
                <div class="form-group">
                    <label class="form-label">角色名称</label>
                    <input type="text" id="char-name" class="form-input" placeholder="输入你的角色名称" maxlength="20">
                </div>
                <div class="form-group">
                    <label class="form-label">种族</label>
                    <select id="char-race" class="form-select">
                        <option value="">选择种族</option>
                    </select>
                </div>
            </div>
            <div class="form-row">
                <div class="form-group">
                    <label class="form-label">职业</label>
                    <select id="char-profession" class="form-select">
                        <option value="">选择职业</option>
                    </select>
                    <button id="custom-profession-btn" type="button" class="btn-secondary" style="margin-top: 8px; width: 100%;">
                        <i class="fas fa-plus"></i> 自定义职业
                    </button>
                </div>
                <div class="form-group">
                    <label class="form-label">等级</label>
                    <select id="char-level" class="form-select">
                        <!-- 等级选项由JS生成 -->
                    </select>
                </div>
            </div>
            <div class="form-row">
                <div class="form-group">
                    <label class="form-label">性别/年龄</label>
                    <input type="text" id="char-gender-age" class="form-input" placeholder="例如：男/25" maxlength="20">
                </div>
                <div class="form-group full-width">
                    <label class="form-label">故事开始地点</label>
                    <select id="char-location" class="form-select">
                        <option value="">选择故事开始地点</option>
                    </select>
                </div>
            </div>
            <div class="form-row">
                <div class="form-group full-width">
                    <label class="form-label">外貌特征</label>
                    <textarea id="char-appearance" class="form-textarea" placeholder="描述角色的外貌，如身高、体型、发色、瞳色、特殊标记等..." style="height: 60px;"></textarea>
                </div>
            </div>
            <div class="form-row">
                <div class="form-group full-width">
                    <label class="form-label">性格特点</label>
                    <textarea id="char-personality" class="form-textarea" placeholder="描述角色的核心性格特征，如勇敢、谨慎、善良等..." style="height: 60px;"></textarea>
                </div>
            </div>

            <!-- 种族天赋显示 -->
            <div id="talent-display" class="talent-display" style="display: none;">
                <div style="font-weight: bold; color: var(--accent-red); margin-bottom: 10px;">
                    <i class="fas fa-star"></i> 种族天赋
                </div>
                <div id="talent-list"></div>
                <div id="special-note" class="special-note" style="display: none;">
                    <i class="fas fa-exclamation-triangle"></i>
                    <span id="special-note-text"></span>
                </div>
            </div>
        </div>

        <!-- 属性加点 -->
        <div class="parchment-card">
            <div class="card-title">属性加点</div>
            <div class="points-remaining">
                剩余自由点数: <span id="points-remaining">0</span>
            </div>
            <div class="stats-container" id="stats-container">
                <!-- 属性项由JS生成 -->
            </div>

            <!-- 资源预览 -->
            <div class="resource-preview">
                <div class="resource-item">
                    <div class="resource-icon hp"><i class="fas fa-heart"></i></div>
