        // 属性名称列表
        const statNames = ['力量', '敏捷', '体质', '智力', '感知', '魅力'];

        // 属性描述
        const statDescriptions = {
            '力量': '影响物理伤害、负重',
            '敏捷': '影响行动速度、闪避',
            '体质': '影响生命值、体力值',
            '智力': '影响法力值、法术伤害',
            '感知': '影响侦测、命中',
            '魅力': '影响社交、交易'
        };

        // ==================== 状态管理 ====================
        let currentState = {
            name: '',
            genderAge: '',
            appearance: '',
            personality: '',
            race: null,
            profession: null,
            level: 1,
            location: null,
            background: '',
            allocatedPoints: { 力量: 0, 敏捷: 0, 体质: 0, 智力: 0, 感知: 0, 魅力: 0 }
        };

        // ==================== 初始化 ====================
        document.addEventListener('DOMContentLoaded', function() {
            initSelects();
            initStatsContainer();
            bindEvents();
            updateAll();
        });

        // 初始化下拉选择框
        function initSelects() {
            // 种族选择
            const raceSelect = document.getElementById('char-race');
            races.forEach(race => {
                const option = document.createElement('option');
                option.value = race.name;
                option.textContent = `${race.name} - ${race.desc}`;
                raceSelect.appendChild(option);
            });

            // 职业选择
            const professionSelect = document.getElementById('char-profession');
            professions.forEach(prof => {
                const option = document.createElement('option');
                option.value = prof.name;
                option.textContent = `${prof.name} - ${prof.desc}`;
                professionSelect.appendChild(option);
            });

            // 等级选择 (1-20)
            const levelSelect = document.getElementById('char-level');
            for (let i = 1; i <= 20; i++) {
                const option = document.createElement('option');
                option.value = i;
                option.textContent = `等级 ${i}`;
                levelSelect.appendChild(option);
            }
            levelSelect.value = 1;

            // 故事开始地点选择
            const locationSelect = document.getElementById('char-location');
            startLocations.forEach(loc => {
                const option = document.createElement('option');
                option.value = loc.name;
                option.textContent = `${loc.name} - ${loc.atmosphere}`;
                locationSelect.appendChild(option);
            });
        }

        // 初始化属性容器
        function initStatsContainer() {
            const container = document.getElementById('stats-container');
            container.innerHTML = '';

            statNames.forEach(stat => {
                const statItem = document.createElement('div');
                statItem.className = 'stat-item';
                statItem.innerHTML = `
                    <div class="stat-header">
                        <span class="stat-name">${stat}</span>
                        <span class="stat-values" id="stat-values-${stat}">
                            基础: 0 | 种族: +0 | 分配: 0
                        </span>
                    </div>
                    <div class="stat-bar-container">
                        <button class="stat-btn" data-stat="${stat}" data-action="decrease">−</button>
                        <div class="stat-bar">
                            <div class="stat-bar-fill" id="stat-bar-${stat}" style="width: 0%"></div>
                        </div>
                        <button class="stat-btn" data-stat="${stat}" data-action="increase">+</button>
                        <span class="stat-total" id="stat-total-${stat}">0</span>
                    </div>
                    <div style="font-size: 0.8rem; color: var(--ink-light); margin-top: 4px;">
                        ${statDescriptions[stat]}
                    </div>
                `;
                container.appendChild(statItem);
            });
        }

        // 绑定事件
        function bindEvents() {
            // 种族选择
            document.getElementById('char-race').addEventListener('change', function() {
                const race = races.find(r => r.name === this.value);
                currentState.race = race;
                updateTalentDisplay();
                updateEquipmentPreview();
                updateStats();
            });

            // 职业选择
            document.getElementById('char-profession').addEventListener('change', function() {
                let prof = professions.find(p => p.name === this.value);
                if (!prof) {
                    prof = customProfessions.find(p => p.name === this.value);
                }
                if (prof) {
                    currentState.profession = prof;
                    updateEquipmentPreview();
                    updateStats();
                }
            });

            // 等级选择
            document.getElementById('char-level').addEventListener('change', function() {
                currentState.level = parseInt(this.value) || 1;
                updateStats();
            });

            // 故事开始地点选择
            document.getElementById('char-location').addEventListener('change', function() {
                const loc = startLocations.find(l => l.name === this.value);
                currentState.location = loc;
                updateEquipmentPreview();
            });

            // 名称输入
            document.getElementById('char-name').addEventListener('input', function() {
                currentState.name = this.value;
            });

            // 背景输入
            document.getElementById('char-background').addEventListener('input', function() {
                currentState.background = this.value;
            });

            // 性别/年龄输入
            document.getElementById('char-gender-age').addEventListener('input', function() {
                currentState.genderAge = this.value;
            });

            // 外貌特征输入
            document.getElementById('char-appearance').addEventListener('input', function() {
                currentState.appearance = this.value;
            });

            // 性格特点输入
            document.getElementById('char-personality').addEventListener('input', function() {
                currentState.personality = this.value;
            });

            // 属性加点按钮
            document.querySelectorAll('.stat-btn').forEach(btn => {
                btn.addEventListener('click', function() {
                    const stat = this.dataset.stat;
                    const action = this.dataset.action;

                    if (action === 'increase') {
                        const remaining = getRemainingPoints();
                        if (remaining > 0) {
                            currentState.allocatedPoints[stat]++;
                        }
                    } else if (action === 'decrease') {
                        if (currentState.allocatedPoints[stat] > 0) {
                            currentState.allocatedPoints[stat]--;
                        }
                    }

                    updateStats();
                });
            });

            // 存档按钮
            document.getElementById('btn-save').addEventListener('click', showSaveModal);

            // 读取存档按钮
            document.getElementById('btn-load').addEventListener('click', showLoadModal);

            // 开始冒险按钮
            document.getElementById('btn-start').addEventListener('click', startGame);

            // 模态框关闭
            document.getElementById('modal-close').addEventListener('click', closeModal);
            document.getElementById('save-modal').addEventListener('click', function(e) {
                if (e.target === this) {
                    closeModal();
                }
            });
        }

        // ==================== 更新函数 ====================

        function updateAll() {
            updateTalentDisplay();
            updateStats();
            updateEquipmentPreview();
        }

        // 更新天赋显示
        function updateTalentDisplay() {
            const display = document.getElementById('talent-display');
            const list = document.getElementById('talent-list');
            const specialNote = document.getElementById('special-note');
            const specialNoteText = document.getElementById('special-note-text');

            if (!currentState.race) {
                display.style.display = 'none';
                return;
            }

            display.style.display = 'block';
            list.innerHTML = '';

            currentState.race.talents.forEach(talent => {
                const item = document.createElement('div');
                item.className = 'talent-item';
                item.innerHTML = `
                    <span class="talent-icon"><i class="fas fa-star"></i></span>
                    <div class="talent-content">
                        <div class="talent-name">${talent.name}</div>
                        <div class="talent-desc">${talent.desc}</div>
                    </div>
                `;
                list.appendChild(item);
            });

            // 特殊提示（魔族）
            if (currentState.race.specialNote) {
                specialNote.style.display = 'block';
                specialNoteText.textContent = currentState.race.specialNote;
            } else {
                specialNote.style.display = 'none';
            }
        }

        // 更新属性显示
        function updateStats() {
            const baseStats = currentState.profession ? currentState.profession.baseStats : 
                { 力量: 0, 敏捷: 0, 体质: 0, 智力: 0, 感知: 0, 魅力: 0 };
            const raceBonus = currentState.race ? currentState.race.statBonus : 
                { 力量: 0, 敏捷: 0, 体质: 0, 智力: 0, 感知: 0, 魅力: 0 };

            // 计算种族天赋属性加成
            const talentBonus = { 力量: 0, 敏捷: 0, 体质: 0, 智力: 0, 感知: 0, 魅力: 0 };
            if (currentState.race && currentState.race.talents) {
                currentState.race.talents.forEach(talent => {
                    if (talent.statEffect) {
                        statNames.forEach(stat => {
                            talentBonus[stat] += talent.statEffect[stat] || 0;
                        });
                    }
                });
            }

            // 解析装备加成
            const equipBonuses = getEquipmentStatBonuses();

            statNames.forEach(stat => {
                const base = baseStats[stat] || 0;
                const bonus = raceBonus[stat] || 0;
                const tBonus = talentBonus[stat];
                const eBonus = equipBonuses.statBonus[stat];
                const allocated = currentState.allocatedPoints[stat] || 0;
                const total = base + bonus + tBonus + eBonus + allocated;

                // 更新数值显示
                const valuesEl = document.getElementById(`stat-values-${stat}`);
                const bonusStr = bonus >= 0 ? `+${bonus}` : `${bonus}`;
                const tBonusStr = tBonus > 0 ? `+${tBonus}` : (tBonus < 0 ? `${tBonus}` : '0');
                const eBonusStr = eBonus > 0 ? `+${eBonus}` : (eBonus < 0 ? `${eBonus}` : '0');
                valuesEl.textContent = `基础: ${base} | 种族: ${bonusStr} | 天赋: ${tBonusStr} | 装备: ${eBonusStr} | 分配: ${allocated}`;

                // 更新进度条
                const barEl = document.getElementById(`stat-bar-${stat}`);
                const percentage = Math.min(total / 20 * 100, 100);
                barEl.style.width = `${percentage}%`;

                // 更新总值
                const totalEl = document.getElementById(`stat-total-${stat}`);
                totalEl.textContent = total;
            });

            // 更新剩余点数
            const remaining = getRemainingPoints();
            document.getElementById('points-remaining').textContent = remaining;

            // 更新资源预览
            updateResourcePreview();

            // 更新按钮状态
            updateStatButtons();
        }

        // 获取剩余点数
        // 统一公式：1级不给初始点数，之后每升1级获得3点（与rpg_frontend_v2保持一致）
        function getRemainingPoints() {
            const freePoints = Math.max(0, (currentState.level - 1) * 3);
            const usedPoints = Object.values(currentState.allocatedPoints).reduce((a, b) => a + b, 0);
            return freePoints - usedPoints;
        }

        // 更新属性按钮状态
        function updateStatButtons() {
            const remaining = getRemainingPoints();

            statNames.forEach(stat => {
                const buttons = document.querySelectorAll(`.stat-btn[data-stat="${stat}"]`);
                buttons.forEach(btn => {
                    if (btn.dataset.action === 'increase') {
                        btn.disabled = remaining <= 0;
                    } else {
                        btn.disabled = currentState.allocatedPoints[stat] <= 0;
                    }
                });
            });
        }

        // 更新资源预览
        function updateResourcePreview() {
            const stats = calculateFinalStats();
            const equipBonuses = getEquipmentStatBonuses();

            // 基础公式 + 装备资源加成（法力+15 等）
            const hp = stats.体质.total * 10 + 50 + equipBonuses.resourceBonus.hp;
            const sp = stats.体质.total * 5 + stats.力量.total * 3 + 20 + equipBonuses.resourceBonus.sp;
            const mp = stats.智力.total * 8 + 20 + equipBonuses.resourceBonus.mp;

            document.getElementById('preview-hp').textContent = hp;
            document.getElementById('preview-sp').textContent = sp;
            document.getElementById('preview-mp').textContent = mp;
        }

        // 解析装备加成：从装备 bonus 字符串中提取六维属性加成和资源加成
        // 例: "法力+15, 魅力+2" → { statBonus: {魅力:2, ...}, resourceBonus: {mp:15, hp:0, sp:0} }
        function getEquipmentStatBonuses() {
            const result = {
                statBonus: { 力量: 0, 敏捷: 0, 体质: 0, 智力: 0, 感知: 0, 魅力: 0 },
                resourceBonus: { hp: 0, sp: 0, mp: 0 }
            };
            if (!currentState.profession || !currentState.profession.startingEquipment) return result;

            Object.values(currentState.profession.startingEquipment).forEach(item => {
                if (!item.bonus || item.slot === '背包') return;
                // 按中英文逗号分割，逐段解析
                const parts = item.bonus.split(/[,，]\s*/);
                for (const part of parts) {
                    const match = part.trim().match(/^(力量|敏捷|体质|智力|感知|魅力|法力|生命|体力)\s*([+-]\d+)/);
                    if (match) {
                        const name = match[1];
                        const value = parseInt(match[2]);
                        if (statNames.includes(name)) {
                            result.statBonus[name] += value;
                        } else if (name === '法力') {
                            result.resourceBonus.mp += value;
                        } else if (name === '生命') {
                            result.resourceBonus.hp += value;
                        } else if (name === '体力') {
                            result.resourceBonus.sp += value;
                        }
                    }
                }
            });

            return result;
        }

        // 计算最终属性
        function calculateFinalStats() {
            const baseStats = currentState.profession ? currentState.profession.baseStats : 
                { 力量: 0, 敏捷: 0, 体质: 0, 智力: 0, 感知: 0, 魅力: 0 };
            const raceBonus = currentState.race ? currentState.race.statBonus : 
                { 力量: 0, 敏捷: 0, 体质: 0, 智力: 0, 感知: 0, 魅力: 0 };

            // 计算种族天赋提供的属性加成（statEffect）
            const talentBonus = { 力量: 0, 敏捷: 0, 体质: 0, 智力: 0, 感知: 0, 魅力: 0 };
            if (currentState.race && currentState.race.talents) {
                currentState.race.talents.forEach(talent => {
                    if (talent.statEffect) {
                        statNames.forEach(stat => {
                            talentBonus[stat] += talent.statEffect[stat] || 0;
                        });
                    }
                });
            }

            // 解析装备属性加成
            const equipBonuses = getEquipmentStatBonuses();

            const finalStats = {};

            statNames.forEach(stat => {
                const raceTotal = (raceBonus[stat] || 0) + talentBonus[stat];
                const equipBonus = equipBonuses.statBonus[stat];
                finalStats[stat] = {
                    base: baseStats[stat] || 0,
                    raceBonus: raceBonus[stat] || 0,
                    talentBonus: talentBonus[stat],
                    equipBonus: equipBonus,
                    allocated: currentState.allocatedPoints[stat] || 0,
                    total: (baseStats[stat] || 0) + raceTotal + equipBonus + (currentState.allocatedPoints[stat] || 0)
                };
            });

            return finalStats;
        }

        // 更新装备预览
        function updateEquipmentPreview() {
            const equippedList = document.getElementById('equipped-list');
            const backpackList = document.getElementById('backpack-list');

            // 已装备物品
            if (currentState.profession && currentState.profession.startingEquipment) {
                const equipment = currentState.profession.startingEquipment;
                let html = '';

                Object.entries(equipment).forEach(([slot, item]) => {
                    if (item.slot !== '背包') {
                        const effectStr = item.specialEffect ? ` | ${item.specialEffect}` : '';
                        html += `
                            <div class="equipment-item">
                                <div>
                                    <span class="equipment-name">${item.name}</span>
                                    <span class="equipment-source">职业</span>
                                </div>
                                <span class="equipment-bonus">${item.bonus || '无'}${effectStr}</span>
                            </div>
                        `;
                    }
                });

                equippedList.innerHTML = html || '<div style="color: var(--ink-light); text-align: center; padding: 10px;">无装备</div>';
            } else {
                equippedList.innerHTML = '<div style="color: var(--ink-light); text-align: center; padding: 10px;">选择职业后显示</div>';
            }

            // 背包物品
            let backpackHtml = '';

            // 种族物品
            if (currentState.race && currentState.race.startingItems) {
                currentState.race.startingItems.forEach(item => {
                    backpackHtml += `
                        <div class="equipment-item">
                            <span class="equipment-name">${item}</span>
                            <span class="equipment-source">种族</span>
                        </div>
                    `;
                });
            }

            // 故事开始地点物品
            if (currentState.location && currentState.location.startingItems) {
                currentState.location.startingItems.forEach(item => {
                    backpackHtml += `
                        <div class="equipment-item">
                            <span class="equipment-name">${item}</span>
                            <span class="equipment-source">地点</span>
                        </div>
                    `;
                });
            }

            // 职业工具（如果有背包物品）
            if (currentState.profession && currentState.profession.startingEquipment) {
                Object.entries(currentState.profession.startingEquipment).forEach(([slot, item]) => {
                    if (item.slot === '背包') {
                        backpackHtml += `
                            <div class="equipment-item">
                                <span class="equipment-name">${item.name}</span>
                                <span class="equipment-source">职业</span>
                            </div>
                        `;
                    }
                });
            }

            backpackList.innerHTML = backpackHtml || '<div style="color: var(--ink-light); text-align: center; padding: 10px;">选择种族和故事开始地点后显示</div>';
        }

        // ==================== 存档功能 ====================

        function showSaveModal() {
            const modal = document.getElementById('save-modal');
            const title = document.getElementById('modal-title');
            const body = document.getElementById('modal-body');

            title.textContent = '保存角色卡';
            body.innerHTML = `
                <div class="form-group">
                    <label class="form-label">存档名称</label>
                    <input type="text" id="save-name" class="form-input" placeholder="输入存档名称" value="${currentState.name || '新角色'}">
                </div>
                <button class="btn btn-success" style="width: 100%; margin-top: 15px;" id="confirm-save">
                    <i class="fas fa-save"></i> 确认保存
                </button>
            `;

            document.getElementById('confirm-save').addEventListener('click', function() {
                const saveName = document.getElementById('save-name').value.trim() || '新角色';
                saveCharacterCard(saveName);
            });

            modal.classList.add('active');
        }

        function showLoadModal() {
            const modal = document.getElementById('save-modal');
            const title = document.getElementById('modal-title');
            const body = document.getElementById('modal-body');

            title.textContent = '读取存档';

            const saves = listCharacterCards();

            if (saves.length === 0) {
                body.innerHTML = '<div class="no-saves">暂无存档</div>';
            } else {
                let html = '';
                saves.forEach(save => {
                    html += `
                        <div class="save-slot">
                            <div class="save-info">
                                <div class="save-name">${save.characterName}</div>
                                <div class="save-details">
                                    ${save.timestamp ? new Date(save.timestamp).toLocaleString() : '未知时间'}
                                </div>
                            </div>
                            <div class="save-actions">
                                <button class="save-btn load" data-slot="${save.slotName}">读取</button>
                                <button class="save-btn delete" data-slot="${save.slotName}">删除</button>
                            </div>
                        </div>
                    `;
                });
                body.innerHTML = html;

                // 绑定读取按钮
                body.querySelectorAll('.save-btn.load').forEach(btn => {
                    btn.addEventListener('click', function() {
                        loadCharacterCard(this.dataset.slot);
                    });
                });

                // 绑定删除按钮
                body.querySelectorAll('.save-btn.delete').forEach(btn => {
                    btn.addEventListener('click', function() {
                        deleteCharacterCard(this.dataset.slot);
                    });
                });
            }

            modal.classList.add('active');
        }

        function closeModal() {
            document.getElementById('save-modal').classList.remove('active');
        }

        function saveCharacterCard(slotName) {
            const saveData = {
                version: "1.1",
                timestamp: new Date().toISOString(),
                character: {
                    name: currentState.name,
                    genderAge: currentState.genderAge,
                    appearance: currentState.appearance,
                    personality: currentState.personality,
                    race: currentState.race ? currentState.race.name : '',
                    profession: currentState.profession ? currentState.profession.name : '',
                    level: currentState.level,
                    location: currentState.location ? currentState.location.name : '',
                    background: currentState.background,
                    allocatedPoints: { ...currentState.allocatedPoints }
                }
            };

            // 获取现有存档
            const saves = JSON.parse(localStorage.getItem('characterCards') || '{}');
            saves[slotName] = saveData;
            localStorage.setItem('characterCards', JSON.stringify(saves));

            showToast('角色卡已保存', 'success');
            closeModal();
        }

        function loadCharacterCard(slotName) {
            const saves = JSON.parse(localStorage.getItem('characterCards') || '{}');
            const saveData = saves[slotName];

            if (!saveData) {
                showToast('存档不存在', 'error');
                return;
            }

            const char = saveData.character;

            // 恢复状态
            currentState.name = char.name || '';
            currentState.genderAge = char.genderAge || '';
            currentState.appearance = char.appearance || '';
            currentState.personality = char.personality || '';
            currentState.race = races.find(r => r.name === char.race) || null;
            currentState.profession = professions.find(p => p.name === char.profession) || customProfessions.find(p => p.name === char.profession) || null;
            currentState.level = char.level || 1;
            currentState.location = startLocations.find(l => l.name === char.location) || null;
            currentState.background = char.background || '';
            currentState.allocatedPoints = char.allocatedPoints || { 力量: 0, 敏捷: 0, 体质: 0, 智力: 0, 感知: 0, 魅力: 0 };

            // 更新表单
            document.getElementById('char-name').value = currentState.name;
            document.getElementById('char-gender-age').value = currentState.genderAge || '';
            document.getElementById('char-appearance').value = currentState.appearance || '';
            document.getElementById('char-personality').value = currentState.personality || '';
            document.getElementById('char-race').value = currentState.race ? currentState.race.name : '';
            document.getElementById('char-profession').value = currentState.profession ? currentState.profession.name : '';
            document.getElementById('char-level').value = currentState.level;
            document.getElementById('char-location').value = currentState.location ? currentState.location.name : '';
            document.getElementById('char-background').value = currentState.background;

            // 更新显示
            updateAll();

            showToast('角色卡已读取', 'success');
            closeModal();
        }

        function listCharacterCards() {
            const saves = JSON.parse(localStorage.getItem('characterCards') || '{}');
            return Object.entries(saves).map(([slotName, data]) => ({
                slotName,
                characterName: data.character?.name || '未知',
                timestamp: data.timestamp,
                version: data.version
            }));
        }

        function deleteCharacterCard(slotName) {
            const saves = JSON.parse(localStorage.getItem('characterCards') || '{}');

            if (!saves[slotName]) {
                showToast('存档不存在', 'error');
                return;
            }

            delete saves[slotName];
            localStorage.setItem('characterCards', JSON.stringify(saves));

            showToast('存档已删除', 'success');
            showLoadModal(); // 刷新列表
        }

        // ==================== 开始游戏 ====================

        async function startGame() {
            // 验证必填项
            if (!currentState.name) {
                showToast('请输入角色名称', 'error');
                return;
            }
            if (!currentState.race) {
                showToast('请选择种族', 'error');
                return;
            }
            if (!currentState.profession) {
                showToast('请选择职业', 'error');
                return;
            }
            if (!currentState.location) {
                showToast('请选择故事开始地点', 'error');
                return;
            }

            // 检查自由点数是否分配完毕
            const remaining = getRemainingPoints();
            if (remaining > 0) {
                if (!confirm(`你还有 ${remaining} 点自由点数未分配，确定要开始游戏吗？`)) {
                    return;
                }
            }

            // 显示加载状态
            const startBtn = document.getElementById('btn-start');
            const originalText = startBtn.innerHTML;
            startBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> 初始化中...';
            startBtn.disabled = true;

            try {
                // 构建角色数据
                const characterData = buildCharacterData();

                // ====== 在任何异步操作之前，先写入 localStorage（供 rpg_frontend_v2 读取） ======
                // 同步已使用的自由点数
                const usedPoints = Object.values(currentState.allocatedPoints).reduce((a, b) => a + b, 0);
                localStorage.setItem('rpg_usedFreePoints', usedPoints.toString());
                console.log('[角色卡开场] 已同步已使用点数到localStorage:', usedPoints);

                // 存储初始基础属性总和（供 rpg_frontend_v2 自由点数推导使用）
                // 公式：profession baseStats 总和 + race statBonus 总和 + race talent statEffect 总和
                if (currentState.profession && currentState.profession.baseStats && currentState.race && currentState.race.statBonus) {
                    const profBaseTotal = Object.values(currentState.profession.baseStats).reduce((a, b) => a + b, 0);
                    const raceBonusTotal = Object.values(currentState.race.statBonus).reduce((a, b) => a + b, 0);
                    // 计算种族天赋属性加成总和
                    let talentBonusTotal = 0;
                    if (currentState.race.talents) {
                        currentState.race.talents.forEach(talent => {
                            if (talent.statEffect) {
                                talentBonusTotal += Object.values(talent.statEffect).reduce((a, b) => a + b, 0);
                            }
                        });
                    }
                    // 装备属性加成总和（如魅力+2等直接加到六维的装备加成）
                    const equipBonuses = getEquipmentStatBonuses();
                    const equipBonusTotal = Object.values(equipBonuses.statBonus).reduce((a, b) => a + b, 0);
                    const initialBaseTotal = profBaseTotal + raceBonusTotal + talentBonusTotal + equipBonusTotal;
                    localStorage.setItem('rpg_initialBaseAttrTotal', initialBaseTotal.toString());
                    console.log('[角色卡开场] 初始基础属性总和:', initialBaseTotal, '(职业:', profBaseTotal, '+ 种族:', raceBonusTotal, '+ 天赋:', talentBonusTotal, '+ 装备:', equipBonusTotal, ')');
                }
                // ====== localStorage 写入结束 ======

                // 检查嵌入数据是否已配置
                if (!EMBEDDED_TEMPLATE || !EMBEDDED_PRESET) {
                    const missingItems = [];
                    if (!EMBEDDED_TEMPLATE) missingItems.push('数据库模板');
                    if (!EMBEDDED_PRESET) missingItems.push('剧情预设');

                    showToast(`数据注入失败：${missingItems.join('、')}未配置，请使用「游戏数据注入工具.html」生成并替换嵌入数据`, 'error');
                    return;
                }

                // 调用初始化接口
                if (window.parent && window.parent.AutoCardUpdaterAPI) {
                    const api = window.parent.AutoCardUpdaterAPI;

                    // 处理预设数据格式：可能是对象或数组
                    let presetDataToUse = EMBEDDED_PRESET;
                    console.log('[游戏初始化] EMBEDDED_PRESET 类型:', typeof EMBEDDED_PRESET);
                    console.log('[游戏初始化] EMBEDDED_PRESET 是否为数组:', Array.isArray(EMBEDDED_PRESET));
                    console.log('[游戏初始化] EMBEDDED_PRESET 是否为 null:', EMBEDDED_PRESET === null);

                    if (Array.isArray(EMBEDDED_PRESET)) {
                        presetDataToUse = EMBEDDED_PRESET[0];
                        console.log('[游戏初始化] 从数组中提取第一个元素');
                    }

                    console.log('[游戏初始化] 最终 presetDataToUse 类型:', typeof presetDataToUse);
                    console.log('[游戏初始化] presetDataToUse.name:', presetDataToUse ? presetDataToUse.name : 'N/A');

                    // ★ 步骤1: 显式注入表格模板到当前聊天（确保运行时表结构包含所有列）
                    // 必须在 initGameSession 之前执行，否则 writeDataToTables 往旧表结构写数据会失败
                    console.log('[游戏初始化] 步骤1: 显式注入表格模板到当前聊天...');
                    if (api.importTemplateFromData) {
                        try {
                            const templateResult = await api.importTemplateFromData(EMBEDDED_TEMPLATE, {
                                scope: 'chat',
                                presetName: characterData.name || '角色卡模板'
                            });
                            console.log('[游戏初始化] 模板注入结果:', templateResult);
                            if (!templateResult.success) {
                                console.warn('[游戏初始化] 模板注入失败:', templateResult.message);
                            }
                        } catch (templateErr) {
                            console.warn('[游戏初始化] 模板注入异常(非致命):', templateErr);
                        }
                    } else {
                        console.warn('[游戏初始化] importTemplateFromData 接口不可用，跳过显式模板注入');
                    }

                    // ★ 步骤2: 初始化游戏会话（模板已在 chat scope，initGameSession 会使用它创建表）
                    console.log('[游戏初始化] 步骤2: 初始化游戏会话...');
                    if (!api.initGameSession) {
                        showToast('数据注入失败：initGameSession 接口不可用', 'error');
                        return;
                    }

                    const result = await api.initGameSession(characterData, {
                        injectTemplate: true,
                        loadPreset: true,
                        presetName: '西幻剧情引导',
                        templateData: EMBEDDED_TEMPLATE,
                        presetData: presetDataToUse
                    });

                    if (!result.success) {
                        showToast('数据注入失败: ' + (result.message || '未知错误'), 'error');
                        return;
                    }

                    // ★ 步骤3: 暖机建表（触发 _ensureTablesFromTemplate → 建表 + 重建 NameMapper）
                    // 只需对主角信息表做一次暖机，确保 NameMapper 正确后再正式写入
                    console.log('[游戏初始化] 步骤3: 暖机建表...');
                    try {
                        const warmupIndex = await api.insertRow({
                            tableName: '主角信息',
                            data: { '人物名称': '__warmup__' },
                            skipNotify: true
                        });
                        console.log('[游戏初始化] 暖机插入结果:', warmupIndex);
                        if (warmupIndex !== -1 && warmupIndex > 0) {
                            await api.deleteRow({
                                tableName: '主角信息',
                                rowIndex: warmupIndex,
                                skipNotify: true
                            });
                            console.log('[游戏初始化] 暖机行已删除');
                        }
                    } catch (warmupErr) {
                        console.log('[游戏初始化] 暖机建表完成（INSERT 失败是正常的）:', warmupErr.message || warmupErr);
                    }

                    // ★ 步骤4: 先发送消息到酒馆，再执行耗时的表格写入
                    // 原因：initGameSession 内部 _notifyTableUpdate 会触发前端刷新，
                    // 如果 sendToTavern 在 writeDataToTables（可能耗时15s）之后执行，
                    // iframe 上下文可能已被销毁，导致消息永远无法发出。
                    console.log('[角色卡开场] 步骤4: 发送消息到酒馆...');
                    sendToTavern(characterData);
                    console.log('[角色卡开场] sendToTavern已调用');

                    // 将角色数据写入数据库表格（带15s超时保护）
                    // 放在 sendToTavern 之后，不阻塞消息发送
                    console.log('[角色卡开场] 开始写入角色数据到表格...');
                    let writeResult = false;
                    try {
                        const writePromise = writeDataToTables(characterData);
                        const writeTimeout = new Promise((_, reject) =>
                            setTimeout(() => reject(new Error('写入超时(15s)')), 15000)
                        );
                        writeResult = await Promise.race([writePromise, writeTimeout]);
                    } catch (writeErr) {
                        console.warn('[角色卡开场] 表格写入超时或异常(非致命):', writeErr);
                    }
                    console.log('[角色卡开场] 表格写入结果:', writeResult ? '全部成功' : '部分失败/超时');

                    // 锁定"已用自由点数"列，防止AI填表时修改（需要模板已导入该列）
                    // 该列由前端加点系统独占管理，只有玩家通过UI分配自由点数时才允许更新
                    try {
                        const lockApi = window.parent ? window.parent.AutoCardUpdaterAPI : null;
                        const tableData = lockApi ? lockApi.exportTableAsJson() : null;
                        if (tableData) {
                            for (const [sheetKey, sheetInfo] of Object.entries(tableData)) {
                                if (sheetInfo && sheetInfo.name === '主角信息') {
                                    const headers = sheetInfo.content && sheetInfo.content[0];
                                    // 检查"已用自由点数"列是否存在（模板导入后才有）
                                    if (headers && headers.includes('已用自由点数')) {
                                        const colIdx = headers.indexOf('已用自由点数');
                                        if (lockApi.lockTableCol) {
                                            lockApi.lockTableCol(sheetKey, colIdx, true);
                                            console.log('[角色卡开场] 已锁定主角信息表"已用自由点数"列(sheetKey:', sheetKey, ', colIdx:', colIdx, ')');
                                        }
                                    } else {
                                        console.log('[角色卡开场] 主角信息表暂无"已用自由点数"列，跳过锁定（需重新导入模板）');
                                    }
                                    break;
                                }
                            }
                        }
                    } catch (lockErr) {
                        console.warn('[角色卡开场] 锁定自由点数列失败(非致命):', lockErr);
                    }

                    showToast('游戏开始！', 'success');
                } else {
                    showToast('数据注入失败：AutoCardUpdaterAPI 接口不可用，请确保在酒馆扩展中打开此页面', 'error');
                }
            } catch (error) {
                console.error('初始化失败:', error);
                showToast('数据注入失败: ' + error.message, 'error');
            } finally {
                startBtn.innerHTML = originalText;
                startBtn.disabled = false;
            }
        }

        /**
         * 将角色数据写入数据库表格
         * 在 initGameSession 成功后调用，使用 insertRow 写入所有角色相关数据
         * @param {Object} characterData - buildCharacterData() 构建的角色数据
         */
        async function writeDataToTables(characterData) {
            const api = window.parent ? window.parent.AutoCardUpdaterAPI : null;
            if (!api) {
                console.error('[writeDataToTables] API不可用');
                return false;
            }

            const stats = characterData.stats;

            try {
                // ---- 只写入主角信息表（包含已用自由点数） ----
                // 其他表（技能/装备/背包/任务等）由 AI 在游戏过程中自行填写
                const expNeeded = Math.round(100 * Math.pow(1.5, characterData.level));
                const hpMax = characterData.resources.hp;
                const spMax = characterData.resources.sp;
                const mpMax = characterData.resources.mp;

                console.log('[writeDataToTables] 写入主角信息表...');
                const result = await api.insertRow({
                    tableName: '主角信息',
                    data: {
                        '人物名称': characterData.name,
                        '性别/年龄': characterData.genderAge || '未设定',
                        '外貌特征': characterData.appearance || '未描述',
                        '职业': characterData.profession,
                        '性格特点': characterData.personality || '未描述',
                        '当前等级': characterData.level,
                        '当前经验值': `0/${expNeeded}`,
                        '力量': stats.力量.total,
                        '敏捷': stats.敏捷.total,
                        '体质': stats.体质.total,
                        '智力': stats.智力.total,
                        '感知': stats.感知.total,
                        '魅力': stats.魅力.total,
                        '生命值': `${hpMax}/${hpMax}`,
                        '体力值': `${spMax}/${spMax}`,
                        '法力值': `${mpMax}/${mpMax}`,
                        '已用自由点数': characterData.usedFreePoints || 0
                    },
                    skipNotify: true
                });

                if (result === -1) {
                    console.warn('[writeDataToTables] 主角信息表插入失败');
                    return false;
                }

                console.log('[writeDataToTables] 主角信息表写入成功, rowIndex:', result);

                // 刷新世界书
                try {
                    const refreshPromise = api.refreshDataAndWorldbook();
                    const timeoutPromise = new Promise((_, reject) =>
                        setTimeout(() => reject(new Error('刷新超时(5s)')), 5000)
                    );
                    await Promise.race([refreshPromise, timeoutPromise]);
                    console.log('[writeDataToTables] 世界书刷新成功');
                } catch (e) {
                    console.warn('[writeDataToTables] 世界书刷新失败(非致命):', e);
                }

                return true;
            } catch (e) {
                console.error('[writeDataToTables] 写入过程异常:', e);
                return false;
            }
        }

        /**
         * 解析物品名称中的数量后缀
         * "干粮x3" → { name: "干粮", quantity: 3 }
         * "铁剑" → { name: "铁剑", quantity: 1 }
         */
        function parseItemName(rawName) {
            const match = rawName.match(/^(.+?)\s*[xX×]\s*(\d+)$/);
            if (match) {
                return { name: match[1], quantity: parseInt(match[2]) };
            }
            return { name: rawName, quantity: 1 };
        }

        function buildCharacterData() {
            const stats = calculateFinalStats();
            const equipment = generateEquipment();

            // 构建技能详情列表
            const professionSkills = [];
            if (currentState.profession && currentState.profession.skills) {
                currentState.profession.skills.forEach(skill => {
                    if (typeof skill === 'string') {
                        // 预设职业：skills 是字符串数组，使用默认值
                        professionSkills.push({
                            name: skill,
                            type: '主动',
                            desc: `${skill}的基础效果`,
                            costType: '无',
                            costValue: 0
                        });
                    } else if (skill && typeof skill === 'object') {
                        // 自定义职业：skills 是对象数组，包含完整数据
                        professionSkills.push({
                            name: skill.name || '未命名技能',
                            type: skill.type || '主动',
                            desc: skill.desc || `${skill.name || '未命名技能'}的基础效果`,
                            costType: skill.costType || '无',
                            costValue: skill.costValue || 0
                        });
                    }
                });
            }

            return {
                name: currentState.name,
                genderAge: currentState.genderAge,
                appearance: currentState.appearance,
                personality: currentState.personality,
                race: currentState.race.name,
                profession: currentState.profession.name,
                professionDesc: currentState.profession.desc || '',
                level: currentState.level,
                location: currentState.location.name,
                background: currentState.background,
                stats: stats,
                talents: currentState.race.talents,
                equipment: equipment,
                professionSkills: professionSkills,
                usedFreePoints: Object.values(currentState.allocatedPoints).reduce((a, b) => a + b, 0),
                resources: (() => {
                    const eb = getEquipmentStatBonuses().resourceBonus;
                    return {
                        hp: stats.体质.total * 10 + 50 + eb.hp,
                        sp: stats.体质.total * 5 + stats.力量.total * 3 + 20 + eb.sp,
                        mp: stats.智力.total * 8 + 20 + eb.mp
                    };
                })()
            };
        }

        function generateEquipment() {
            const equipment = [];

            // 职业装备
            if (currentState.profession && currentState.profession.startingEquipment) {
                Object.entries(currentState.profession.startingEquipment).forEach(([slot, item]) => {
                    equipment.push({
                        ...item,
                        source: '职业',
                        equipped: item.slot !== '背包'
                    });
                });
            }

            // 种族物品
            if (currentState.race && currentState.race.startingItems) {
                currentState.race.startingItems.forEach(item => {
                    equipment.push({
                        name: item,
                        type: '物品',
                        slot: '背包',
                        source: '种族',
                        equipped: false
                    });
                });
            }

            // 故事开始地点物品
            if (currentState.location && currentState.location.startingItems) {
                currentState.location.startingItems.forEach(item => {
                    equipment.push({
                        name: item,
                        type: '物品',
                        slot: '背包',
                        source: '故事开始地点',
                        equipped: false
                    });
                });
            }

            return equipment;
        }

        function sendToTavern(characterData) {
            console.log('[sendToTavern] 开始执行');
            const message = buildCharacterMessage(characterData);
            console.log('[sendToTavern] 消息长度:', message.length, '前100字:', message.substring(0, 100));

            // 使用与游戏开始页面.html一致的发送逻辑
            // 注入成功后直接发送，无需延迟
            const sendTextarea = parent.document.getElementById('send_textarea');
            console.log('[sendToTavern] send_textarea找到:', !!sendTextarea);
            if (sendTextarea) {
                const textarea = parent.document.getElementById('send_textarea');
                const sendButton = parent.document.getElementById('send_but');
                console.log('[sendToTavern] send_but找到:', !!sendButton);

                if (textarea && sendButton) {
                    textarea.value = message;
                    console.log('[sendToTavern] 已设置textarea值，准备点击发送按钮');
                    sendButton.click();
                    console.log('[sendToTavern] 发送按钮已点击');
                } else {
                    console.error('[sendToTavern] 无法找到textarea或sendButton');
                    showToast('无法找到酒馆输入框或发送按钮', 'error');
                }
            } else {
                console.error('[sendToTavern] 无法找到send_textarea');
                showToast('无法连接到酒馆，请确保在酒馆扩展中打开此页面', 'error');
            }
        }

        function buildCharacterMessage(data) {
            const { name, genderAge, appearance, personality, race, profession, professionDesc, level, location, background, stats, equipment, talents, resources, professionSkills } = data;

            // 格式化属性（含装备加成分解）
            const formatStat = (statName) => {
                const s = stats[statName];
                const talentStr = s.talentBonus ? `+天赋${s.talentBonus >= 0 ? '+' : ''}${s.talentBonus}` : '';
                const equipStr = s.equipBonus ? `+装备${s.equipBonus >= 0 ? '+' : ''}${s.equipBonus}` : '';
                return `${statName}: ${s.total} (基础${s.base}+种族${s.raceBonus >= 0 ? '+' : ''}${s.raceBonus}${talentStr}${equipStr}+分配${s.allocated})`;
            };

            // 分类装备
            const equippedItems = equipment.filter(e => e.equipped);
            const backpackItems = equipment.filter(e => !e.equipped);

            // 职业描述行
            const descLine = professionDesc ? `\n职业描述：${professionDesc}` : '';

            // 技能详情
            const skillsSection = professionSkills && professionSkills.length > 0
                ? professionSkills.map(s => {
                    const costStr = s.costType !== '无' ? ` | 消耗: ${s.costType}${s.costValue}` : '';
                    return `• ${s.name}[${s.type}] - ${s.desc}${costStr}`;
                }).join('\n')
                : '无';

            return `【角色创建完成】

════════════════════════════
【基本信息】
════════════════════════════
姓名：${name}
性别/年龄：${genderAge || '未设定'}
种族：${race}
职业：${profession}${descLine}
等级：${level}
故事开始地点：${location}

════════════════════════════
【外貌与性格】
════════════════════════════
外貌特征：${appearance || '未描述'}
性格特点：${personality || '未描述'}

════════════════════════════
【种族天赋】
════════════════════════════
${talents.map(t => `• ${t.name}: ${t.desc}`).join('\n')}

════════════════════════════
【职业技能】
════════════════════════════
${skillsSection}

════════════════════════════
【六维属性】
════════════════════════════
${formatStat('力量')} | ${formatStat('敏捷')} | ${formatStat('体质')}
${formatStat('智力')} | ${formatStat('感知')} | ${formatStat('魅力')}

════════════════════════════
【资源】
════════════════════════════
生命值：${resources.hp} | 体力值：${resources.sp} | 法力值：${resources.mp}

════════════════════════════
【初始装备】
════════════════════════════
${equippedItems.map(e => {
    const effectStr = e.specialEffect ? ` | 特殊: ${e.specialEffect}` : '';
    return `【${e.slot}】${e.name} - ${e.bonus || '无'}${effectStr}`;
}).join('\n') || '无'}

════════════════════════════
【背包物品】
════════════════════════════
${backpackItems.map(e => `• ${e.name} [${e.source}]`).join('\n') || '无'}

════════════════════════════
【背景故事】
════════════════════════════
${background || '（未填写）'}

---
请根据以上角色信息开始游戏。故事从${location}开始。`.trim();
        }

        // ==================== 工具函数 ====================

