            function createSkillEntry() {
                skillCounter++;
                const entry = document.createElement('div');
                entry.className = 'skill-entry';
                entry.style.cssText = 'border: 1px solid var(--border); padding: 10px; margin-bottom: 8px; border-radius: 6px; background: var(--bg-secondary);';
                entry.innerHTML = `
