                // 消耗类型联动：选"无"时强制消耗数值为0
                entry.querySelector('.skill-cost-type').addEventListener('change', function() {
                    const costValueInput = entry.querySelector('.skill-cost-value');
                    if (this.value === '无') {
                        costValueInput.value = 0;
