                const stats = {
                    力量: parseInt(document.getElementById('custom-str').value) || 6,
                    敏捷: parseInt(document.getElementById('custom-agi').value) || 6,
                    体质: parseInt(document.getElementById('custom-vit').value) || 6,
                    智力: parseInt(document.getElementById('custom-int').value) || 6,
                    感知: parseInt(document.getElementById('custom-per').value) || 6,
                    魅力: parseInt(document.getElementById('custom-cha').value) || 6
                };

                // 验证总点数
                const total = Object.values(stats).reduce((a, b) => a + b, 0);
                if (total !== 36) {
                    showToast('属性总点数必须为36点！', 'error');
                    return;
                }

                if (!name) {
                    showToast('请输入职业名称！', 'error');
                    return;
