                    const skillName = entry.querySelector('.skill-name').value.trim();
                    if (!skillName) {
                        hasEmptySkillName = true;
                        return;
                    }
                    skills.push({
                        name: skillName,
                        type: entry.querySelector('.skill-type').value,
                        desc: entry.querySelector('.skill-desc').value.trim() || `${skillName}的基础效果`,
                        costType: entry.querySelector('.skill-cost-type').value,
                        costValue: parseInt(entry.querySelector('.skill-cost-value').value) || 0
                    });
                });

                if (hasEmptySkillName) {
                    showToast('请填写所有技能名称，或删除空白技能条目', 'error');
                    return;
                }

                // 至少需要一个技能
                if (skills.length === 0) {
                    showToast('请至少添加一个技能', 'error');
                    return;
                }

                // 创建自定义职业
                const weaponName = document.getElementById('custom-weapon-name').value.trim() || '自定义武器';
