                            type: "武器",
                            slot: weaponSlot,
                            bonus: weaponBonus,
                            specialEffect: weaponEffect
                        },
                        armor: {
                            name: armorName,
                            type: "防具",
                            slot: armorSlot,
                            bonus: armorBonus,
                            specialEffect: armorEffect
                        }
                    },
                    skills: skills,
                    isCustom: true
                };

                customProfessions.push(customProfession);

                // 添加到职业下拉框
                const select = document.getElementById('char-profession');
                const option = document.createElement('option');
                option.value = name;
                option.textContent = name;
                select.appendChild(option);
                select.value = name;

                // 更新职业显示
                currentState.profession = customProfession;
                updateEquipmentPreview();
                updateStats();

                modal.remove();
                showToast('自定义职业 "' + name + '" 创建成功！', 'success');
            });
        });
    </script>
